    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'タップ / ダイス', 'タップ／ダイス', 'Tarô tạo ren trong / bàn ren tạo ren ngoài', '', '', '', 19);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'マシニングセンタ', 'マシニングセンタ', 'Trung tâm gia công có thay dao tự động', '', '', '', 20);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'インバータ', 'インバータ', 'Biến tần', '', '', '', 21);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'ブロックゲージ', 'ブロックゲージ', 'Căn mẫu chuẩn chiều dài', '', '', '', 22);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'リンギング', 'リンギング', 'Ghép bám mặt đo căn mẫu', '', '', '', 23);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'サインバー', 'サインバー', 'Thước sin dùng đo hoặc thiết lập góc', '', '', '', 24);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'トースカン / Vブロック', 'トースカン／ブイブロック', 'Đài vạch / khối V', '', '', '', 25);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'ピストンポンプ', 'ピストンポンプ', 'Bơm piston', '', '', '', 26);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'ベーンポンプ', 'ベーンポンプ', 'Bơm cánh gạt', '', '', '', 27);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'ジグ / ブシュ', 'ジグ／ブシュ', 'Đồ gá / bạc dẫn hướng', '', '', '', 28);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'モジュール', 'モジュール', 'Môđun bánh răng', '', '', '', 29);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'チップブレーカ', 'チップブレーカ', 'Bộ phận bẻ phoi', '', '', '', 30);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'クレータ / フランク摩耗', 'クレータ／フランクまもう', 'Mòn lõm mặt trước / mòn mặt sau', '', '', '', 31);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'ダイカスト', 'ダイカスト', 'Đúc áp lực', '', '', '', 32);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'コールド / ホットチャンバ', 'コールド／ホットチャンバ', 'Buồng lạnh / buồng nóng', '', '', '', 33);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'ブリネル / ビッカース / ショア', 'ブリネル／ビッカース／ショア', 'Brinell / Vickers / Shore', '', '', '', 34);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Thuật ngữ viết tắt và katakana', 'コラム / ニー / サドル', 'コラム／ニー／サドル', 'Cột máy / bệ nâng / bàn trượt', '', '', '', 35);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～とは、～をいう。', '～とは、～をいう。', '“X là / được gọi là Y.” Xác định đúng đối tượng định nghĩa, nhất là tên dụng cụ hoặc dạng mòn.', '', '', '', 36);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '一般に、～。', 'いっぱんに、～。', '“Nhìn chung, …” Đánh giá đặc tính thông thường; không lấy trường hợp đặc biệt để thay quy tắc của đề.', '', '', '', 37);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～によれば、～。', '～によれば、～。', '“Theo …” Kiểm tra định nghĩa, ký hiệu hoặc yêu cầu của quy định được nêu.', '', '', '', 38);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～よりも～のほうが～。', '～よりも～のほうが～。', '“So với A, B … hơn.” Xác định thứ tự A/B và đặc tính so sánh: bôi trơn, làm mát, độ cứng.', '', '', '', 39);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～に比べて～。', '～にくらべて～。', '“So với …” Xác định chiều tăng hoặc giảm trước khi chọn đúng/sai.', '', '', '', 40);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～の場合／～とき、～。', '～のばあい／～とき、～。', '“Trong trường hợp / khi …” Không bỏ điều kiện: cùng số cực, cùng độ trượt, thay đá mài.', '', '', '', 41);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～が同じ場合／同一の～において', '～がおなじばあい／どういつの～において', '“Khi … giống nhau / trong cùng …” Giữ các điều kiện này cố định khi so sánh.', '', '', '', 42);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～が一定のとき', '～がいっていのとき', '“Khi … không đổi.” Trong V = πDN/1000, nếu N không đổi thì V tăng theo D.', '', '', '', 43);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～ほど、～。', '～ほど、～。', '“Càng … càng …” Kiểm tra quan hệ tăng/giảm; lưu ý câu có thể khẳng định quá mức.', '', '', '', 44);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '次の式で表される。', 'つぎのしきであらわされる。', '“Được biểu diễn bằng công thức sau.” Kiểm tra tử/mẫu, đơn vị và hệ số đổi đơn vị.', '', '', '', 45);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', 'ただし、～とする。', 'ただし、～とする。', '“Trong đó / với quy ước …” Đọc đầy đủ định nghĩa biến và điều kiện áp dụng.', '', '', '', 46);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～の一つとして、～がある。', '～のひとつとして、～がある。', '“Một trong các … là …” Chỉ cần ví dụ được nêu thuộc nhóm đó, không cần là lựa chọn duy nhất.', '', '', '', 47);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～以上／～以下', '～いじょう／～いか', '“Từ … trở lên / không quá …” Bao gồm giá trị bằng ngưỡng.', '', '', '', 48);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～しなければならない。', '～しなければならない。', '“Phải …” Với câu an toàn, đọc đúng hành động bắt buộc và thời điểm thực hiện.', '', '', '', 49);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '下図の～は～である。', 'かずの～は～である。', '“X trong hình dưới là Y.” Đối chiếu trực tiếp hình, nhãn và vị trí lưỡi cắt; không bỏ hình.', '', '', '', 50);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～を表す。', '～をあらわす。', '“Biểu thị …” Kiểm tra đúng đại lượng: mz là đường kính vòng chia, không phải đường kính ngoài.', '', '', '', 51);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '前もって～／徐々に～', 'まえもって～／じょじょに～', '“Trước đó / từ từ.” Giữ đúng trình tự thao tác: có lỗ trước khi doa; tăng tải dần trong thử kéo.', '', '', '', 52);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Mẫu câu thường gặp trong đề', '～を取り去ると、元の形に戻る。', '～をとりさると、もとのかたちにもどる。', '“Khi bỏ …, trở lại hình dạng cũ.” Nhận biết đàn hồi và điều kiện tải nằm trong giới hạn.', '', '', '', 53);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Strategy', 1, '中ぐり盤では、主軸と共に回転するバイトで、前もってあけられた下穴をくり広げる加工ができる。', 'Trên máy doa, có thể dùng dao tiện quay cùng trục chính để gia công mở rộng lỗ sơ bộ đã được tạo trước đó.', NULL, '○', 'Máy doa gia công lỗ có sẵn bằng dao gắn trên trục quay. Dao cắt phần vật liệu ở thành lỗ để tăng đường kính và cải thiện độ chính xác. Cụm 前もってあけられた下穴 cho biết đã có lỗ trước khi doa; không nhầm thao tác này với khoan tạo lỗ từ vật liệu đặc.', '[{"term": "中ぐり盤", "reading": "なかぐりばん", "meaning": "máy doa"}, {"term": "主軸", "reading": "しゅじく", "meaning": "trục chính"}, {"term": "下穴", "reading": "したあな", "meaning": "lỗ sơ bộ, lỗ mồi"}, {"term": "くり広げる", "reading": "くりひろげる", "meaning": "doa rộng, mở rộng lỗ"}]'::jsonb, 1);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Strategy', 2, '次に示す切削工具材料の硬度を比較した場合、以下の順序は正しい。  
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Strategy', 3, '切削油剤は、一般に、不水溶性よりも水溶性のほうが潤滑性がよい。', 'Nhìn chung, dung dịch cắt gọt hòa tan trong nước có tính bôi trơn tốt hơn loại không hòa tan trong nước.', NULL, '×', 'Thông thường, dầu cắt gọt không hòa tan trong nước có khả năng bôi trơn tốt hơn; loại pha nước có ưu thế về làm mát. Phát biểu đã nhầm 潤滑性 với 冷却作用. Khi đọc câu so sánh, xác định rõ đặc tính đang được so sánh trước khi chọn đúng/sai.', '[{"term": "切削油剤", "reading": "せっさくゆざい", "meaning": "chất lỏng cắt gọt"}, {"term": "不水溶性", "reading": "ふすいようせい", "meaning": "không hòa tan trong nước"}, {"term": "水溶性", "reading": "すいようせい", "meaning": "hòa tan trong nước"}, {"term": "潤滑性", "reading": "じゅんかつせい", "meaning": "tính bôi trơn"}]'::jsonb, 3);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Strategy', 4, '同じ温度において、マシン油の ISO VG10 は、ISO VG32 よりも、動粘度の数値が小さい油である。', 'Ở cùng nhiệt độ, dầu máy ISO VG10 có trị số độ nhớt động học nhỏ hơn dầu ISO VG32.', NULL, '○', 'Số của cấp ISO VG biểu thị cấp độ nhớt động học danh nghĩa ở 40 °C. VG10 có giá trị danh nghĩa khoảng 10 mm²/s, còn VG32 khoảng 32 mm²/s; vì vậy VG10 nhỏ hơn. Điều kiện cùng nhiệt độ rất quan trọng vì độ nhớt thay đổi theo nhiệt độ. Không hiểu số cấp là giá trị chính xác ở mọi nhiệt độ.', '[{"term": "同じ温度", "reading": "おなじおんど", "meaning": "cùng nhiệt độ"}, {"term": "マシン油", "reading": "マシンゆ", "meaning": "dầu máy"}, {"term": "動粘度", "reading": "どうねんど", "meaning": "độ nhớt động học"}, {"term": "数値", "reading": "すうち", "meaning": "trị số"}]'::jsonb, 4);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Strategy', 5, 'ピストンポンプは、一般に、ベーンポンプに比べて高吐出圧力を得ることができる。', 'Nhìn chung, bơm piston có thể tạo áp suất đầu ra cao hơn bơm cánh gạt.', NULL, '○', 'Bơm piston thường phù hợp với hệ thống thủy lực áp suất cao hơn bơm cánh gạt. Cơ cấu piston và xy lanh cho phép tạo áp lực lớn. Câu hỏi so sánh khả năng đạt áp suất, không so sánh lưu lượng hay độ ồn; 高吐出圧力 là điểm quyết định.', '[{"term": "ピストンポンプ", "reading": "ピストンポンプ", "meaning": "bơm piston"}, {"term": "ベーンポンプ", "reading": "ベーンポンプ", "meaning": "bơm cánh gạt"}, {"term": "吐出圧力", "reading": "としゅつあつりょく", "meaning": "áp suất đầu ra"}, {"term": "比べて", "reading": "くらべて", "meaning": "so với"}]'::jsonb, 5);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Strategy', 6, 'ジグ用ブシュの材質には、一般に、アルミニウムを使用する。', 'Nhìn chung, nhôm được dùng làm vật liệu chế tạo bạc dẫn hướng của đồ gá.', NULL, '×', 'Bạc dẫn hướng đồ gá phải chống mài mòn khi tiếp xúc với dụng cụ và duy trì vị trí dẫn hướng chính xác. Vì thế thường dùng thép được tôi cứng hoặc vật liệu chịu mài mòn phù hợp, không dùng nhôm làm lựa chọn thông thường. Điểm dễ nhầm là vật liệu thân đồ gá có thể khác vật liệu bạc dẫn hướng.', '[{"term": "ジグ", "reading": "ジグ", "meaning": "đồ gá dẫn hướng dụng cụ"}, {"term": "ブシュ", "reading": "ブシュ", "meaning": "bạc, ống lót dẫn hướng"}, {"term": "材質", "reading": "ざいしつ", "meaning": "chất liệu"}, {"term": "アルミニウム", "reading": "アルミニウム", "meaning": "nhôm"}]'::jsonb, 6);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Management', 7, '二つのブロックゲージの測定面を重ね合わせ、密着させることをリンギングという。', 'Việc áp chồng hai mặt đo của hai căn mẫu và làm chúng bám sát nhau được gọi là wringing (リンギング).', NULL, '○', 'リンギング là thao tác làm các mặt đo rất phẳng, sạch của căn mẫu bám vào nhau để ghép được chiều dài chuẩn. Cần phân biệt ghép bám mặt đo với việc chỉ đặt hai căn mẫu cạnh nhau. Bề mặt sạch và tình trạng mặt đo ảnh hưởng trực tiếp đến khả năng bám và độ chính xác.', '[{"term": "ブロックゲージ", "reading": "ブロックゲージ", "meaning": "căn mẫu"}, {"term": "測定面", "reading": "そくていめん", "meaning": "mặt đo"}, {"term": "密着", "reading": "みっちゃく", "meaning": "bám sát"}, {"term": "リンギング", "reading": "リンギング", "meaning": "ghép bám căn mẫu"}]'::jsonb, 7);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Management', 8, '特性要因図とは、特定の結果(特性)と要因との関係を系統的に表した図をいう。', 'Biểu đồ nhân quả là sơ đồ biểu diễn một cách có hệ thống quan hệ giữa một kết quả cụ thể (đặc tính) và các yếu tố gây ra nó.', NULL, '○', 'Biểu đồ 特性要因図, thường có dạng xương cá, đặt kết quả cần phân tích ở đầu và nhóm các nguyên nhân vào các nhánh. Nó giúp tìm và sắp xếp nguyên nhân có thể ảnh hưởng đến chất lượng. Không nhầm với biểu đồ Pareto, vốn dùng để xếp hạng các nhóm theo mức độ hoặc tần suất.', '[{"term": "特性要因図", "reading": "とくせいよういんず", "meaning": "biểu đồ nhân quả, xương cá"}, {"term": "特性", "reading": "とくせい", "meaning": "đặc tính"}, {"term": "要因", "reading": "よういん", "meaning": "yếu tố, nguyên nhân"}, {"term": "系統的", "reading": "けいとうてき", "meaning": "có hệ thống"}]'::jsonb, 8);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Management', 9, '平行軸に取り付けられた一対のはすば歯車のねじれ方向は、同じである。', 'Một cặp bánh răng nghiêng lắp trên hai trục song song có cùng hướng xoắn răng.', NULL, '×', 'Với cặp bánh răng nghiêng ăn khớp ngoài trên các trục song song, hai hướng xoắn phải ngược nhau: một bên phải và một bên trái. Nếu cùng hướng xoắn thì không tạo thành cặp ăn khớp ngoài thông thường như câu hỏi. Chú ý điều kiện 平行軸; không áp dụng kết luận này tùy tiện cho mọi kiểu bố trí bánh răng.', '[{"term": "平行軸", "reading": "へいこうじく", "meaning": "trục song song"}, {"term": "はすば歯車", "reading": "はすばはぐるま", "meaning": "bánh răng nghiêng"}, {"term": "ねじれ方向", "reading": "ねじれほうこう", "meaning": "hướng xoắn"}, {"term": "一対", "reading": "いっつい", "meaning": "một cặp"}]'::jsonb, 9);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Management', 10, 'けがき作業において、丸棒の端面の中心を求める方法の一つとして、トースカンとVブロックを用いる方法がある。', 'Trong công việc vạch dấu, một phương pháp xác định tâm mặt đầu của thanh tròn là dùng đài vạch và khối V.', NULL, '○', 'Khối V đỡ thanh tròn, còn đài vạch tạo các đường dấu trên mặt đầu. Bằng cách thay đổi hướng đặt hoặc xoay thanh và lấy giao điểm các đường thích hợp, có thể xác định tâm. Khối V tạo vị trí đỡ ổn định; đài vạch thực hiện vạch dấu, không phải dụng cụ cắt tạo tâm.', '[{"term": "けがき作業", "reading": "けがきさぎょう", "meaning": "công việc vạch dấu"}, {"term": "丸棒", "reading": "まるぼう", "meaning": "thanh tròn"}, {"term": "端面", "reading": "たんめん", "meaning": "mặt đầu"}, {"term": "トースカン", "reading": "トースカン", "meaning": "đài vạch"}]'::jsonb, 10);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Management', 11, '日本産業規格(JIS)によれば、鉄工やすりの複目やすりには、上目と下目がある。', 'Theo Tiêu chuẩn công nghiệp Nhật Bản (JIS), giũa sắt có răng kép gồm lớp răng trên và lớp răng dưới.', NULL, '○', 'Giũa răng kép có hai nhóm rãnh răng cắt chéo nhau, được gọi là 上目 và 下目. Sự kết hợp này tạo nhiều điểm cắt trên bề mặt. 複目 nói về kiểu bố trí răng; không đồng nghĩa với mức độ thô hay mịn của giũa.', '[{"term": "鉄工やすり", "reading": "てっこうやすり", "meaning": "giũa sắt"}, {"term": "複目", "reading": "ふくめ", "meaning": "răng kép"}, {"term": "上目", "reading": "うわめ", "meaning": "lớp răng trên"}, {"term": "下目", "reading": "しため", "meaning": "lớp răng dưới"}]'::jsonb, 11);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Management', 12, '鋳造とは、溶かした金属を型に流し込み、冷却凝固させて製品をつくる方法である。', 'Đúc là phương pháp tạo sản phẩm bằng cách rót kim loại nóng chảy vào khuôn rồi làm nguội để kim loại đông đặc.', NULL, '○', 'Chuỗi thao tác mô tả đúng bản chất của đúc: nấu chảy → rót vào khuôn → làm nguội, đông đặc. Hình dạng sản phẩm được quyết định chủ yếu bởi lòng khuôn. Phân biệt với rèn, trong đó vật liệu được tạo hình bằng lực ép hoặc va đập thay vì rót kim loại lỏng.', '[{"term": "鋳造", "reading": "ちゅうぞう", "meaning": "đúc"}, {"term": "金属", "reading": "きんぞく", "meaning": "kim loại"}, {"term": "流し込む", "reading": "ながしこむ", "meaning": "rót vào"}, {"term": "冷却凝固", "reading": "れいきゃくぎょうこ", "meaning": "làm nguội và đông đặc"}]'::jsonb, 12);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Management', 13, '鋳鉄は、炭素鋼よりも炭素の含有量が少ない。', 'Gang có hàm lượng cacbon thấp hơn thép cacbon.', NULL, '×', 'Gang chứa nhiều cacbon hơn thép cacbon. Ranh giới phân loại thường dùng nằm khoảng 2% cacbon; gang thường ở phía hàm lượng cao hơn. Vì thế từ 少ない làm phát biểu sai. Không suy ra hàm lượng cacbon từ tên gọi 鉄 mà phải phân biệt loại vật liệu 鋳鉄 và 炭素鋼.', '[{"term": "鋳鉄", "reading": "ちゅうてつ", "meaning": "gang"}, {"term": "炭素鋼", "reading": "たんそこう", "meaning": "thép cacbon"}, {"term": "炭素", "reading": "たんそ", "meaning": "cacbon"}, {"term": "含有量", "reading": "がんゆうりょう", "meaning": "hàm lượng"}]'::jsonb, 13);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Management', 14, '鉄鋼の硬さを高める目的で行う熱処理のことを焼なましという。', 'Nhiệt luyện thực hiện nhằm tăng độ cứng của sắt thép được gọi là ủ.', NULL, '×', '焼なまし là ủ: thường làm mềm, giảm ứng suất và cải thiện khả năng gia công bằng cách nung rồi làm nguội chậm. Quá trình thường dùng để tăng độ cứng của thép là 焼入れ (tôi), với làm nguội nhanh sau khi nung thích hợp. Bẫy nằm ở mục đích 硬さを高める, không ở việc có nung nóng hay không.', '[{"term": "熱処理", "reading": "ねつしょり", "meaning": "nhiệt luyện"}, {"term": "焼なまし", "reading": "やきなまし", "meaning": "ủ"}, {"term": "焼入れ", "reading": "やきいれ", "meaning": "tôi"}, {"term": "硬さ", "reading": "かたさ", "meaning": "độ cứng"}]'::jsonb, 14);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Management', 15, '金属材料の硬さを測る方法として、ブリネル硬さ試験、ビッカース硬さ試験、ショア硬さ試験等の方法がある。', 'Các phương pháp đo độ cứng của vật liệu kim loại gồm thử độ cứng Brinell, Vickers, Shore và các phương pháp khác.', NULL, '○', 'Cả ba phương pháp được nêu đều là phương pháp thử độ cứng. Brinell và Vickers đánh giá qua vết lõm do đầu ấn tạo ra; Shore trong thử kim loại đánh giá độ bật lại. Không nhầm thử độ cứng với thử kéo, vốn đo các đặc trưng chịu tải kéo như giới hạn chảy và độ bền kéo.', '[{"term": "硬さ試験", "reading": "かたさしけん", "meaning": "thử độ cứng"}, {"term": "ブリネル", "reading": "ブリネル", "meaning": "Brinell"}, {"term": "ビッカース", "reading": "ビッカース", "meaning": "Vickers"}, {"term": "ショア", "reading": "ショア", "meaning": "Shore"}]'::jsonb, 15);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Management', 16, '安全率は、次式で表される。  
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Management', 17, '日本産業規格(JIS)の材料記号によれば、SCMは、ニッケルクロム鋼鋼材を表す。', 'Theo ký hiệu vật liệu của JIS, SCM biểu thị vật liệu thép niken-crom.', NULL, '×', 'SCM là thép crom-molypden, không phải thép niken-crom. Ký hiệu của thép niken-crom thuộc nhóm SNC; thép niken-crom-molypden thuộc nhóm SNCM. Giữ nguyên SCM khi học để tránh nhầm chữ M với sự có mặt của niken.', '[{"term": "材料記号", "reading": "ざいりょうきごう", "meaning": "ký hiệu vật liệu"}, {"term": "クロム", "reading": "クロム", "meaning": "crom"}, {"term": "モリブデン", "reading": "モリブデン", "meaning": "molypden"}, {"term": "ニッケル", "reading": "ニッケル", "meaning": "niken"}]'::jsonb, 17);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Management', 18, '日本産業規格(JIS)の電気用図記号によれば、下図は、電流計の記号である。
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Management', 19, '定格周波数50Hz、60Hz共用の誘導電動機における回転速度は、極数及びすべりが同じ場合、60Hzで使用するよりも50Hzで使用するほうが高い。', 'Với động cơ cảm ứng dùng chung cho tần số định mức 50 Hz và 60 Hz, nếu số cực và độ trượt giống nhau thì tốc độ quay khi dùng ở 50 Hz cao hơn khi dùng ở 60 Hz.', NULL, '×', 'Tốc độ đồng bộ nₛ = 120f/p, với f là tần số và p là số cực; tốc độ rôto n = (1−s)nₛ. Khi p và độ trượt s không đổi, tốc độ tỷ lệ thuận với f. Do đó tốc độ ở 60 Hz cao hơn ở 50 Hz, theo tỷ lệ 60/50 = 1,2. Phát biểu đảo chiều so sánh.', '[{"term": "定格周波数", "reading": "ていかくしゅうはすう", "meaning": "tần số định mức"}, {"term": "誘導電動機", "reading": "ゆうどうでんどうき", "meaning": "động cơ cảm ứng"}, {"term": "極数", "reading": "きょくすう", "meaning": "số cực"}, {"term": "すべり", "reading": "すべり", "meaning": "độ trượt"}]'::jsonb, 19);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Management', 20, '労働安全衛生規則によれば、常時就業させる場所の作業面の照度は、普通の作業の場合、150ルクス以上としなければならない。', 'Theo Quy định an toàn và vệ sinh lao động, độ rọi trên mặt làm việc ở nơi người lao động làm việc thường xuyên phải đạt ít nhất 150 lux đối với công việc thông thường.', NULL, '○', 'Đáp án chính thức xác nhận ngưỡng 150 lux cho 普通の作業 theo quy định được hỏi. 照度 là độ rọi trên mặt làm việc; 以上 nghĩa là bằng hoặc lớn hơn, nên đúng 150 lux cũng đạt ngưỡng. Cần phân biệt quy định cho nơi làm việc này với quy định riêng về vệ sinh văn phòng; không tự thay ngưỡng của một quy định bằng ngưỡng của quy định khác.', '[{"term": "労働安全衛生規則", "reading": "ろうどうあんぜんえいせいきそく", "meaning": "quy định an toàn và vệ sinh lao động"}, {"term": "作業面", "reading": "さぎょうめん", "meaning": "mặt làm việc"}, {"term": "照度", "reading": "しょうど", "meaning": "độ rọi"}, {"term": "以上", "reading": "いじょう", "meaning": "trở lên, ít nhất"}]'::jsonb, 20);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Technology', 21, '普通旋盤作業では、一般に、コラムを摺動するニーの送りとサドル及びテーブルの送りで加工を進める。', 'Trong công việc tiện trên máy tiện thông thường, nhìn chung việc gia công được tiến hành bằng chuyển động chạy dao của bệ nâng trượt trên cột máy và chuyển động chạy dao của bàn trượt cùng bàn máy.', NULL, '×', 'Mô tả コラム・ニー・サドル・テーブル đặc trưng cho máy phay kiểu bàn nâng, không phải cơ cấu gia công thông thường của máy tiện. Trên máy tiện, phôi quay theo trục chính và dao được đưa bởi bàn xe dao cùng các bàn trượt. Câu sai do gán cơ cấu máy phay sang máy tiện.', '[{"term": "普通旋盤", "reading": "ふつうせんばん", "meaning": "máy tiện thông thường"}, {"term": "コラム", "reading": "コラム", "meaning": "cột máy"}, {"term": "ニー", "reading": "ニー", "meaning": "bệ nâng máy phay"}, {"term": "摺動", "reading": "しゅうどう", "meaning": "trượt trên bề mặt dẫn hướng"}]'::jsonb, 21);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Technology', 22, '日本産業規格(JIS)によれば、普通旋盤の刃物を取り付ける最上部の台を、横送り台という。', 'Theo JIS, bàn nằm trên cùng dùng để gá dao của máy tiện thông thường được gọi là bàn chạy dao ngang.', NULL, '×', 'Bộ phận trực tiếp gá dao ở trên cùng là 刃物台 (ổ gá dao). 横送り台 là bàn chạy dao ngang, tạo chuyển động theo phương ngang so với trục chính. Không nhầm nơi giữ dao với bộ phận nằm dưới có nhiệm vụ tạo chuyển động chạy dao.', '[{"term": "刃物台", "reading": "はものだい", "meaning": "ổ gá dao"}, {"term": "横送り台", "reading": "よこおくりだい", "meaning": "bàn chạy dao ngang"}, {"term": "取り付ける", "reading": "とりつける", "meaning": "lắp, gá"}, {"term": "最上部", "reading": "さいじょうぶ", "meaning": "phần trên cùng"}]'::jsonb, 22);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Technology', 23, '日本産業規格(JIS)によれば、深穴あけは、加工する穴の長さと直径との比が2倍以上の穴をあけることである。', 'Theo JIS, khoan lỗ sâu là khoan lỗ có tỷ số giữa chiều dài lỗ gia công và đường kính từ 2 trở lên.', NULL, '×', 'Định nghĩa được hỏi dùng tỷ số chiều dài lỗ trên đường kính từ 4 trở lên (L/D ≥ 4), không phải từ 2. Ví dụ đường kính 10 mm và chiều dài 40 mm cho L/D = 4. Cần đọc tỷ số là chiều dài chia đường kính, không đảo tử và mẫu. Lỗ càng sâu so với đường kính càng khó thoát phoi và đưa chất lỏng cắt đến lưỡi cắt.', '[{"term": "深穴あけ", "reading": "ふかあなあけ", "meaning": "khoan lỗ sâu"}, {"term": "長さ", "reading": "ながさ", "meaning": "chiều dài"}, {"term": "直径", "reading": "ちょっけい", "meaning": "đường kính"}, {"term": "比", "reading": "ひ", "meaning": "tỷ số"}]'::jsonb, 23);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Technology', 24, '日本産業規格(JIS)によれば、下図のバイトは右勝手である。
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Technology', 25, '高速度工具鋼ドリルは、刃部の材料にステンレス合金を使用したドリルの総称である。', 'Mũi khoan thép dụng cụ tốc độ cao là tên gọi chung của các mũi khoan dùng hợp kim không gỉ làm vật liệu phần lưỡi.', NULL, '×', 'Mũi khoan 高速度工具鋼 có phần cắt bằng thép dụng cụ tốc độ cao (HSS, thường gọi là thép gió). Thép không gỉ là nhóm vật liệu khác, có đặc tính chống ăn mòn; không phải định nghĩa của vật liệu lưỡi mũi khoan HSS. Bẫy là thay tên vật liệu trong cụm 刃部の材料.', '[{"term": "ドリル", "reading": "ドリル", "meaning": "mũi khoan"}, {"term": "刃部", "reading": "じんぶ", "meaning": "phần lưỡi cắt"}, {"term": "ステンレス合金", "reading": "ステンレスごうきん", "meaning": "hợp kim không gỉ"}, {"term": "総称", "reading": "そうしょう", "meaning": "tên gọi chung"}]'::jsonb, 25);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Technology', 26, 'はん用の穴加工に用いるドリルの先端角は、一般に、140°である。', 'Góc đỉnh của mũi khoan dùng cho gia công lỗ thông dụng nhìn chung là 140°.', NULL, '×', 'Mũi khoan xoắn thông dụng thường có góc đỉnh khoảng 118°. Các góc khác có thể được chọn tùy vật liệu và loại mũi khoan, nhưng 140° không phải giá trị thông dụng mà phát biểu này nêu. Phân biệt góc đỉnh giữa hai lưỡi chính với góc xoắn của rãnh mũi khoan.', '[{"term": "はん用", "reading": "はんよう", "meaning": "thông dụng, đa dụng"}, {"term": "穴加工", "reading": "あなかこう", "meaning": "gia công lỗ"}, {"term": "先端角", "reading": "せんたんかく", "meaning": "góc đỉnh"}, {"term": "一般に", "reading": "いっぱんに", "meaning": "nhìn chung"}]'::jsonb, 26);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Technology', 27, '一般に、バイトのすくい角が大きくなるほど、刃先の寿命は長くなる。', 'Nhìn chung, góc trước của dao tiện càng lớn thì tuổi thọ mũi dao càng dài.', NULL, '×', 'Tăng góc trước thường làm cắt nhẹ hơn, nhưng đồng thời làm nêm cắt mỏng hơn và giảm độ bền của lưỡi. Vì vậy không thể kết luận tuổi thọ cứ tăng khi góc trước tăng. Tuổi thọ phụ thuộc cả vật liệu dao, vật liệu phôi và điều kiện cắt; từ ほど tạo quan hệ tăng liên tục không đúng ở đây.', '[{"term": "すくい角", "reading": "すくいかく", "meaning": "góc trước"}, {"term": "刃先", "reading": "はさき", "meaning": "mũi dao, mép cắt"}, {"term": "寿命", "reading": "じゅみょう", "meaning": "tuổi thọ"}, {"term": "大きくなるほど", "reading": "おおきくなるほど", "meaning": "càng lớn thì càng"}]'::jsonb, 27);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Technology', 28, 'ドリル加工でステップ送りとは、送りを数回に分けて加工する穴あけ方法である。', 'Trong gia công bằng mũi khoan, chạy dao theo bước là phương pháp khoan chia chuyển động tiến dao thành nhiều lần.', NULL, '○', 'ステップ送り là khoan từng bước: tiến một đoạn rồi rút hoặc lùi dao theo chu trình, sau đó tiếp tục tiến sâu hơn. Việc chia nhiều lần hỗ trợ bẻ và thoát phoi, giảm nguy cơ tắc phoi trong lỗ. Không hiểu đây là thay đổi số vòng quay; phát biểu nói về cách chia chuyển động chạy dao.', '[{"term": "ステップ送り", "reading": "ステップおくり", "meaning": "chạy dao theo bước, khoan nhấp"}, {"term": "送り", "reading": "おくり", "meaning": "chạy dao"}, {"term": "数回", "reading": "すうかい", "meaning": "nhiều lần"}, {"term": "穴あけ", "reading": "あなあけ", "meaning": "khoan lỗ"}]'::jsonb, 28);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Technology', 29, 'チップブレーカとは、切りくずを適当な長さに切断する目的で、バイトのすくい面に段や溝を設けたものである。', 'Bộ phận bẻ phoi là phần tạo bậc hoặc rãnh trên mặt trước của dao tiện nhằm cắt phoi thành chiều dài thích hợp.', NULL, '○', 'Bậc hoặc rãnh trên mặt trước buộc phoi uốn cong và gãy thành đoạn phù hợp để xử lý. Đó là chức năng của チップブレーカ. Nó không phải dụng cụ riêng để cắt phôi, mà là hình học hoặc bộ phận hỗ trợ kiểm soát phoi tại vùng cắt.', '[{"term": "チップブレーカ", "reading": "チップブレーカ", "meaning": "bộ phận bẻ phoi"}, {"term": "切りくず", "reading": "きりくず", "meaning": "phoi"}, {"term": "段", "reading": "だん", "meaning": "bậc"}, {"term": "溝", "reading": "みぞ", "meaning": "rãnh"}]'::jsonb, 29);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2023', 'Technology', 30, '切削によってすくい面上に生じる摩耗のうち、くぼみが生じた摩耗をクレータ摩耗という。', 'Trong các dạng mòn xuất hiện trên mặt trước do cắt gọt, dạng mòn tạo thành hõm được gọi là mòn lõm (crater wear).', NULL, '○', 'Phoi trượt trên mặt trước, cùng với nhiệt và tương tác vật liệu, có thể tạo hõm mòn trên mặt này. Đó là クレータ摩耗. Phân biệt với フランク摩耗, xuất hiện ở mặt sau khi mặt sau cọ với phôi. Từ すくい面 xác định đúng vị trí của dạng mòn được hỏi.', '[{"term": "摩耗", "reading": "まもう", "meaning": "mài mòn"}, {"term": "くぼみ", "reading": "くぼみ", "meaning": "hõm, chỗ lõm"}, {"term": "クレータ摩耗", "reading": "クレータまもう", "meaning": "mòn lõm mặt trước"}, {"term": "すくい面", "reading": "すくいめん", "meaning": "mặt trước của dao"}]'::jsonb, 30);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Strategy', 1, 'マシニングセンタは、主として回転工具を使用し、フライス削り、中ぐり、穴あけ及びねじ立てを含む複数の切削加工ができ、かつ、加工プログラムに従って工具を自動交換できる数値制御工作機械である。', 'Trung tâm gia công là máy công cụ điều khiển số chủ yếu sử dụng dụng cụ quay, có thể thực hiện nhiều loại gia công cắt gọt gồm phay, doa, khoan và tarô; đồng thời có khả năng tự động thay dụng cụ theo chương trình gia công.', NULL, '○', 'Định nghĩa bao gồm ba đặc trưng quan trọng: dụng cụ chủ yếu quay, thực hiện nhiều nguyên công, và tự động thay dao theo chương trình điều khiển số. Nhờ thay dao tự động, máy thực hiện nhiều thao tác trên cùng phôi. Không nhầm trung tâm gia công với máy chỉ làm được một nguyên công hoặc máy yêu cầu thay mọi dao bằng tay.', '[{"term": "マシニングセンタ", "reading": "マシニングセンタ", "meaning": "trung tâm gia công"}, {"term": "数値制御", "reading": "すうちせいぎょ", "meaning": "điều khiển số"}, {"term": "ねじ立て", "reading": "ねじたて", "meaning": "tarô, tạo ren trong"}, {"term": "自動交換", "reading": "じどうこうかん", "meaning": "thay tự động"}]'::jsonb, 31);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Strategy', 2, '切削用超硬工具材料の識別記号Pは、主に鋳鉄の加工に使用される。', 'Ký hiệu phân loại P của vật liệu dụng cụ cắt hợp kim cứng chủ yếu được dùng để gia công gang.', NULL, '×', 'Nhóm P chủ yếu dành cho gia công thép, trong khi nhóm K thường gắn với gia công gang. Phát biểu đã hoán đổi đối tượng của nhóm vật liệu. Giữ nguyên ký hiệu P khi đối chiếu; đừng suy từ độ cứng của phôi để gán nhóm dụng cụ mà bỏ qua hệ phân loại.', '[{"term": "超硬工具材料", "reading": "ちょうこうこうぐざいりょう", "meaning": "vật liệu dụng cụ hợp kim cứng"}, {"term": "識別記号", "reading": "しきべつきごう", "meaning": "ký hiệu phân loại"}, {"term": "鋳鉄", "reading": "ちゅうてつ", "meaning": "gang"}, {"term": "加工", "reading": "かこう", "meaning": "gia công"}]'::jsonb, 32);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Strategy', 3, '一般に、不水溶性切削油剤よりも水溶性切削油剤のほうが冷却作用が優れている。', 'Nhìn chung, chất lỏng cắt gọt hòa tan trong nước có tác dụng làm mát tốt hơn loại không hòa tan trong nước.', NULL, '○', 'Chất lỏng cắt gọt pha nước thường tản nhiệt tốt, nên ưu thế được hỏi là làm mát. Đây là điểm khác với câu 3 năm 2023, nơi đặc tính được hỏi là bôi trơn và phát biểu sai. Khi cùng hai loại dầu xuất hiện, phải đọc 冷却作用 hay 潤滑性 thay vì nhớ đáp án theo tên dầu.', '[{"term": "冷却作用", "reading": "れいきゃくさよう", "meaning": "tác dụng làm mát"}, {"term": "優れている", "reading": "すぐれている", "meaning": "tốt hơn, vượt trội"}, {"term": "水溶性切削油剤", "reading": "すいようせいせっさくゆざい", "meaning": "chất lỏng cắt gọt pha nước"}, {"term": "不水溶性", "reading": "ふすいようせい", "meaning": "không hòa tan trong nước"}]'::jsonb, 33);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Strategy', 4, '工作機械に使用する潤滑油の効果の一つとして、防錆効果がある。', 'Một trong các tác dụng của dầu bôi trơn dùng cho máy công cụ là chống gỉ.', NULL, '○', 'Dầu tạo màng trên bề mặt kim loại, hạn chế tiếp xúc trực tiếp với nước và môi trường gây gỉ. Vì thế chống gỉ là một chức năng của dầu bôi trơn, bên cạnh giảm ma sát và mài mòn. Cụm 効果の一つ không khẳng định đây là tác dụng duy nhất.', '[{"term": "工作機械", "reading": "こうさくきかい", "meaning": "máy công cụ"}, {"term": "潤滑油", "reading": "じゅんかつゆ", "meaning": "dầu bôi trơn"}, {"term": "防錆", "reading": "ぼうせい", "meaning": "chống gỉ"}, {"term": "効果", "reading": "こうか", "meaning": "tác dụng, hiệu quả"}]'::jsonb, 34);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Strategy', 5, '空気圧装置と油圧装置を比較した場合、一般に、使用圧力が高い場合は、空気圧装置が用いられる。', 'Khi so sánh thiết bị khí nén và thiết bị thủy lực, nhìn chung thiết bị khí nén được dùng trong trường hợp áp suất sử dụng cao.', NULL, '×', 'Hệ thống thủy lực thường được dùng khi cần áp suất và lực lớn. Khí nén thông thường vận hành ở áp suất thấp hơn, và tính nén được của khí cũng ảnh hưởng đến độ cứng vững chuyển động. Phát biểu nhầm khí nén với thủy lực; không đánh đồng áp suất cao với tốc độ chuyển động nhanh.', '[{"term": "空気圧装置", "reading": "くうきあつそうち", "meaning": "thiết bị khí nén"}, {"term": "油圧装置", "reading": "ゆあつそうち", "meaning": "thiết bị thủy lực"}, {"term": "使用圧力", "reading": "しようあつりょく", "meaning": "áp suất sử dụng"}, {"term": "比較", "reading": "ひかく", "meaning": "so sánh"}]'::jsonb, 35);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Strategy', 6, '締金（締板）を使って工作物を締め付ける場合、締付ボルトはできるだけ工作物から離して締め付けるほうがよい。', 'Khi dùng đòn kẹp (tấm kẹp) để kẹp chặt phôi, nên bố trí bu lông kẹp càng xa phôi càng tốt.', NULL, '×', 'Bu lông nên bố trí gần phôi hơn so với điểm đỡ của đòn kẹp để truyền lực kẹp hiệu quả lên phôi. Nếu đặt xa phôi, lợi thế đòn bẩy cho lực kẹp trên phôi giảm. Chú ý cụm 工作物から離して; sai nằm ở hướng bố trí, không ở việc dùng đòn kẹp.', '[{"term": "締金", "reading": "しめがね", "meaning": "đòn kẹp"}, {"term": "締板", "reading": "しめいた", "meaning": "tấm kẹp"}, {"term": "工作物", "reading": "こうさくぶつ", "meaning": "phôi, chi tiết gia công"}, {"term": "締付ボルト", "reading": "しめつけボルト", "meaning": "bu lông kẹp"}]'::jsonb, 36);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 7, '角度を測定するものの一つとして、サインバーがある。', 'Thước sin là một trong các dụng cụ dùng để đo góc.', NULL, '○', 'Thước sin dùng quan hệ sin θ = h/L, trong đó L là khoảng cách giữa tâm hai con lăn và h là chênh lệch độ cao, thường tạo bằng căn mẫu. Nhờ đó có thể thiết lập hoặc kiểm tra góc chính xác. サイン ở đây là hàm sin, không phải chữ ký hay tín hiệu.', '[{"term": "角度", "reading": "かくど", "meaning": "góc"}, {"term": "測定", "reading": "そくてい", "meaning": "đo lường"}, {"term": "サインバー", "reading": "サインバー", "meaning": "thước sin"}, {"term": "ブロックゲージ", "reading": "ブロックゲージ", "meaning": "căn mẫu"}]'::jsonb, 37);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 8, '製品検査方法の一つに、抜取検査がある。', 'Kiểm tra lấy mẫu là một trong các phương pháp kiểm tra sản phẩm.', NULL, '○', '抜取検査 kiểm tra một số sản phẩm lấy từ lô để đưa ra đánh giá về lô theo quy tắc đã đặt. Đây là phương pháp kiểm tra hợp lệ, khác với 全数検査 là kiểm tra toàn bộ. Không hiểu kiểm tra lấy mẫu là tùy ý bỏ kiểm tra; việc chọn mẫu và tiêu chí đánh giá phải có quy định.', '[{"term": "製品検査", "reading": "せいひんけんさ", "meaning": "kiểm tra sản phẩm"}, {"term": "抜取検査", "reading": "ぬきとりけんさ", "meaning": "kiểm tra lấy mẫu"}, {"term": "全数検査", "reading": "ぜんすうけんさ", "meaning": "kiểm tra toàn bộ"}, {"term": "方法", "reading": "ほうほう", "meaning": "phương pháp"}]'::jsonb, 38);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 9, '平歯車のモジュールと歯数をかけた値は、歯車の外径を表す。', 'Giá trị thu được khi nhân môđun với số răng của bánh răng trụ răng thẳng biểu thị đường kính ngoài của bánh răng.', NULL, '×', 'Tích môđun m và số răng z cho đường kính vòng chia d = mz, không phải đường kính ngoài. Với bánh răng tiêu chuẩn không dịch chỉnh, đường kính ngoài dₐ = m(z+2). Ví dụ m = 2 mm và z = 20 thì d = 40 mm, còn dₐ = 44 mm. Phân biệt 外径 với đường kính vòng chia.', '[{"term": "平歯車", "reading": "ひらはぐるま", "meaning": "bánh răng trụ răng thẳng"}, {"term": "モジュール", "reading": "モジュール", "meaning": "môđun bánh răng"}, {"term": "歯数", "reading": "はすう", "meaning": "số răng"}, {"term": "外径", "reading": "がいけい", "meaning": "đường kính ngoài"}]'::jsonb, 39);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 10, 'けがき用コンパスの針先の形状は、丸みを付けて研ぐとよい。', 'Nên mài đầu kim của compa vạch dấu thành hình có độ tròn.', NULL, '×', 'Đầu kim của compa vạch dấu phải được mài nhọn thích hợp để định vị và tạo đường dấu rõ, chính xác. Đầu bo tròn khiến điểm tiếp xúc rộng và dễ trượt, làm giảm độ chính xác. Câu hỏi nói đến đầu kim vạch dấu, không phải một đầu đỡ cần tránh làm xước bề mặt.', '[{"term": "けがき用コンパス", "reading": "けがきようコンパス", "meaning": "compa vạch dấu"}, {"term": "針先", "reading": "はりさき", "meaning": "đầu kim"}, {"term": "丸み", "reading": "まるみ", "meaning": "độ tròn, phần bo tròn"}, {"term": "研ぐ", "reading": "とぐ", "meaning": "mài sắc"}]'::jsonb, 40);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 11, '摺動面の当たりを良くする方法の一つにきさげ作業がある。', 'Cạo rà là một trong các phương pháp cải thiện sự tiếp xúc của các mặt trượt.', NULL, '○', 'Cạo rà loại bỏ có kiểm soát các điểm cao trên mặt trượt, giúp phân bố vùng tiếp xúc và cải thiện độ phù hợp giữa các mặt. Phương pháp thường đi cùng kiểm tra vết tiếp xúc bằng chất màu. 当たり ở đây là tình trạng tiếp xúc bề mặt, không phải va đập.', '[{"term": "摺動面", "reading": "しゅうどうめん", "meaning": "mặt trượt"}, {"term": "当たり", "reading": "あたり", "meaning": "vết, tình trạng tiếp xúc"}, {"term": "きさげ作業", "reading": "きさげさぎょう", "meaning": "công việc cạo rà"}, {"term": "良くする", "reading": "よくする", "meaning": "cải thiện"}]'::jsonb, 41);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 12, 'ダイカスト鋳造法には、コールドチャンバ式、ホットチャンバ式等がある。', 'Các phương pháp đúc áp lực có loại buồng lạnh, loại buồng nóng và các loại khác.', NULL, '○', 'Đúc áp lực được phân loại theo cơ cấu cấp và phun kim loại lỏng, trong đó có buồng lạnh và buồng nóng. Buồng nóng có bộ phận cấp kim loại làm việc gắn với bể kim loại lỏng; buồng lạnh được nạp kim loại vào buồng ép theo từng chu kỳ. Hai tên gọi này là các loại của đúc áp lực, không phải hai kiểu nhiệt luyện.', '[{"term": "ダイカスト", "reading": "ダイカスト", "meaning": "đúc áp lực"}, {"term": "鋳造法", "reading": "ちゅうぞうほう", "meaning": "phương pháp đúc"}, {"term": "コールドチャンバ式", "reading": "コールドチャンバしき", "meaning": "loại buồng lạnh"}, {"term": "ホットチャンバ式", "reading": "ホットチャンバしき", "meaning": "loại buồng nóng"}]'::jsonb, 42);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 13, 'アルミニウムは、鉄よりも熱伝導率が小さい。', 'Nhôm có hệ số dẫn nhiệt nhỏ hơn sắt.', NULL, '×', 'Nhôm dẫn nhiệt tốt hơn sắt trong so sánh vật liệu thông thường được hỏi. Vì vậy 熱伝導率が小さい là sai; phải là lớn hơn. Không nhầm khả năng dẫn nhiệt với nhiệt độ nóng chảy hay khối lượng riêng, vì đó là các tính chất khác nhau.', '[{"term": "アルミニウム", "reading": "アルミニウム", "meaning": "nhôm"}, {"term": "鉄", "reading": "てつ", "meaning": "sắt"}, {"term": "熱伝導率", "reading": "ねつでんどうりつ", "meaning": "hệ số dẫn nhiệt"}, {"term": "小さい", "reading": "ちいさい", "meaning": "nhỏ"}]'::jsonb, 43);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 14, '鉄鋼製品を加熱し、徐冷することを焼入れという。', 'Việc nung nóng sản phẩm sắt thép rồi làm nguội chậm được gọi là tôi.', NULL, '×', 'Tôi (焼入れ) cần làm nguội nhanh sau khi nung thích hợp. Làm nguội chậm (徐冷) là đặc trưng thường gặp của ủ (焼なまし). Hai thao tác đều có bước nung nóng, nên từ phân biệt là 徐冷. Câu 14 năm 2023 cũng kiểm tra sự nhầm lẫn giữa ủ và tôi.', '[{"term": "鉄鋼製品", "reading": "てっこうせいひん", "meaning": "sản phẩm sắt thép"}, {"term": "加熱", "reading": "かねつ", "meaning": "nung nóng"}, {"term": "徐冷", "reading": "じょれい", "meaning": "làm nguội chậm"}, {"term": "焼入れ", "reading": "やきいれ", "meaning": "tôi"}]'::jsonb, 44);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 15, '金属材料の引張試験とは、引張試験機等を用いて、材料を徐々に引っ張り、降伏点、耐力、引張強さ等を測定する試験をいう。', 'Thử kéo vật liệu kim loại là phép thử dùng máy thử kéo hoặc thiết bị tương đương để kéo vật liệu từ từ và đo điểm chảy, giới hạn chảy quy ước, độ bền kéo cùng các đặc trưng khác.', NULL, '○', 'Thử kéo tạo tải kéo tăng dần và theo dõi đáp ứng của mẫu, từ đó xác định các đặc trưng chịu kéo. 降伏点 là điểm chảy; 耐力 thường là ứng suất chảy quy ước khi vật liệu không có điểm chảy rõ. 引張強さ là ứng suất kéo lớn nhất theo định nghĩa của phép thử, không phải độ cứng.', '[{"term": "引張試験", "reading": "ひっぱりしけん", "meaning": "thử kéo"}, {"term": "降伏点", "reading": "こうふくてん", "meaning": "điểm chảy"}, {"term": "耐力", "reading": "たいりょく", "meaning": "giới hạn chảy quy ước"}, {"term": "引張強さ", "reading": "ひっぱりつよさ", "meaning": "độ bền kéo"}]'::jsonb, 45);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 16, '一般に金属は、ある範囲内の大きさまでの荷重であれば、荷重を取り去ると再び元の形に戻る。このような性質を弾性という。', 'Nhìn chung, nếu tải tác dụng lên kim loại có độ lớn trong một phạm vi nhất định, khi bỏ tải thì kim loại trở lại hình dạng ban đầu. Tính chất như vậy được gọi là tính đàn hồi.', NULL, '○', 'Đây là định nghĩa biến dạng đàn hồi: sau khi bỏ tải, biến dạng được phục hồi trong giới hạn đàn hồi. Điều kiện ある範囲内 là thiết yếu; nếu vượt giới hạn thích hợp, biến dạng dẻo có thể còn lại. Không hiểu phát biểu là mọi kim loại luôn trở về hình dạng cũ ở bất kỳ tải nào.', '[{"term": "荷重", "reading": "かじゅう", "meaning": "tải trọng"}, {"term": "取り去る", "reading": "とりさる", "meaning": "loại bỏ"}, {"term": "元の形", "reading": "もとのかたち", "meaning": "hình dạng ban đầu"}, {"term": "弾性", "reading": "だんせい", "meaning": "tính đàn hồi"}]'::jsonb, 46);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 17, '日本産業規格(JIS)によれば、寸法補助記号「C」で表す面取り角度は、30°である。', 'Theo JIS, góc vát mép biểu thị bằng ký hiệu bổ trợ kích thước “C” là 30°.', NULL, '×', 'Ký hiệu C được dùng cho vát mép 45°, không phải 30°. Ví dụ C2 biểu thị vát 45° với kích thước vát tương ứng 2 mm. Nếu góc khác 45°, cần thể hiện góc và kích thước thích hợp; không mặc định mọi vát mép đều ghi bằng C.', '[{"term": "寸法補助記号", "reading": "すんぽうほじょきごう", "meaning": "ký hiệu bổ trợ kích thước"}, {"term": "面取り", "reading": "めんとり", "meaning": "vát mép"}, {"term": "角度", "reading": "かくど", "meaning": "góc"}, {"term": "表す", "reading": "あらわす", "meaning": "biểu thị"}]'::jsonb, 47);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 18, '抵抗値50 Ωの導体に100 Vの直流電圧を加えたとき、流れる電流は2 Aである。', 'Khi đặt điện áp một chiều 100 V vào một vật dẫn có điện trở 50 Ω, dòng điện chạy qua là 2 A.', NULL, '○', 'Áp dụng định luật Ohm: I = U/R = 100/50 = 2 A. Điện áp phải chia cho điện trở để tìm dòng điện; không nhân hai giá trị. Giữ đúng đơn vị: V là vôn, Ω là ôm và A là ampe. Kết quả khớp với phát biểu.', '[{"term": "抵抗値", "reading": "ていこうち", "meaning": "giá trị điện trở"}, {"term": "導体", "reading": "どうたい", "meaning": "vật dẫn"}, {"term": "直流電圧", "reading": "ちょくりゅうでんあつ", "meaning": "điện áp một chiều"}, {"term": "電流", "reading": "でんりゅう", "meaning": "dòng điện"}]'::jsonb, 48);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 19, '三相誘導電動機は、周波数変換器(インバータ)により回転速度を変えることができる。', 'Có thể thay đổi tốc độ quay của động cơ cảm ứng ba pha bằng bộ biến đổi tần số (biến tần).', NULL, '○', 'Biến tần điều chỉnh tần số nguồn cấp, từ đó thay đổi tốc độ đồng bộ và tốc độ vận hành của động cơ cảm ứng. Quan hệ cơ bản nₛ = 120f/p cho thấy khi số cực không đổi, thay đổi f sẽ thay đổi tốc độ. Tốc độ thực còn chịu ảnh hưởng của độ trượt và tải; khả năng điều chỉnh bằng biến tần vẫn đúng.', '[{"term": "三相", "reading": "さんそう", "meaning": "ba pha"}, {"term": "誘導電動機", "reading": "ゆうどうでんどうき", "meaning": "động cơ cảm ứng"}, {"term": "周波数変換器", "reading": "しゅうはすうへんかんき", "meaning": "bộ biến đổi tần số"}, {"term": "インバータ", "reading": "インバータ", "meaning": "biến tần"}]'::jsonb, 49);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Management', 20, '労働安全衛生関係法令によれば、研削といしを取り替えたときは、1分間の試運転をしなければならないと規定されている。', 'Theo các quy định pháp luật về an toàn và vệ sinh lao động, khi thay đá mài phải chạy thử trong 1 phút.', NULL, '×', 'Khi thay đá mài, thời gian chạy thử yêu cầu là ít nhất 3 phút. Ít nhất 1 phút là yêu cầu trước khi bắt đầu công việc trong ngày. Câu đã lấy thời gian của tình huống bắt đầu ngày làm việc để gán cho tình huống thay đá mài. Phải đọc 取り替えたとき trước khi chọn số phút.', '[{"term": "研削といし", "reading": "けんさくといし", "meaning": "đá mài"}, {"term": "取り替える", "reading": "とりかえる", "meaning": "thay thế"}, {"term": "試運転", "reading": "しうんてん", "meaning": "chạy thử"}, {"term": "規定", "reading": "きてい", "meaning": "quy định"}]'::jsonb, 50);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Technology', 21, '普通旋盤の大きさの表し方の一つとして、センタ間の距離がある。', 'Khoảng cách giữa hai mũi tâm là một trong các cách biểu thị kích cỡ máy tiện thông thường.', NULL, '○', 'Khoảng cách giữa các mũi tâm cho biết giới hạn chiều dài phôi có thể gá giữa hai tâm trong cấu hình tương ứng. Đây là một chỉ tiêu kích cỡ máy tiện, bên cạnh các chỉ tiêu như đường kính quay lớn nhất trên băng máy. Cụm 一つ cho phép có nhiều chỉ tiêu, không nói khoảng cách tâm là chỉ tiêu duy nhất.', '[{"term": "センタ", "reading": "センタ", "meaning": "mũi tâm"}, {"term": "センタ間", "reading": "センタかん", "meaning": "giữa hai mũi tâm"}, {"term": "距離", "reading": "きょり", "meaning": "khoảng cách"}, {"term": "大きさ", "reading": "おおきさ", "meaning": "kích cỡ"}]'::jsonb, 51);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Technology', 22, '日本産業規格(JIS)によれば、普通旋盤で、ベッドの前後の案内面が作る平面と主軸中心線との距離を心高という。', 'Theo JIS, trên máy tiện thông thường, khoảng cách giữa mặt phẳng tạo bởi các mặt dẫn hướng phía trước và phía sau của băng máy với đường tâm trục chính được gọi là chiều cao tâm.', NULL, '○', '心高 là khoảng cách theo phương vuông góc từ mặt phẳng dẫn hướng quy ước của băng máy đến đường tâm trục chính. Đây là định nghĩa chiều cao tâm, không phải khoảng cách giữa hai tâm dọc theo trục. Đọc kỹ hai đối tượng được dùng để đo khoảng cách: mặt phẳng dẫn hướng và đường tâm.', '[{"term": "ベッド", "reading": "ベッド", "meaning": "băng máy"}, {"term": "案内面", "reading": "あんないめん", "meaning": "mặt dẫn hướng"}, {"term": "主軸中心線", "reading": "しゅじくちゅうしんせん", "meaning": "đường tâm trục chính"}, {"term": "心高", "reading": "しんだか", "meaning": "chiều cao tâm"}]'::jsonb, 52);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Technology', 23, '切りくず生成機構の分類に基づく切りくずの形態で、せん断形切りくずは（ニ）である。
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Technology', 24, '日本産業規格(JIS)によれば、下図のバイトは左勝手である。
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Technology', 25, '同一の切削条件において、バイトのノーズRを小さくすると、一般に、仕上げ面粗さは悪くなる。', 'Trong cùng điều kiện cắt, nếu giảm bán kính mũi dao R thì nhìn chung độ nhám bề mặt hoàn thiện trở nên xấu hơn.', NULL, '○', 'Ở cùng lượng chạy dao f, bán kính mũi dao r nhỏ hơn để lại vết chạy dao cao hơn. Mô hình hình học thường dùng cho chiều cao nhám lý thuyết là Rz ≈ f²/(8r), nên giảm r làm nhám tăng. Quan hệ này giải thích phát biểu trong điều kiện cắt được giữ giống nhau; thực tế còn chịu ảnh hưởng của rung và vật liệu.', '[{"term": "同一", "reading": "どういつ", "meaning": "giống nhau, cùng"}, {"term": "切削条件", "reading": "せっさくじょうけん", "meaning": "điều kiện cắt"}, {"term": "ノーズR", "reading": "ノーズアール", "meaning": "bán kính mũi dao"}, {"term": "仕上げ面粗さ", "reading": "しあげめんあらさ", "meaning": "độ nhám bề mặt hoàn thiện"}]'::jsonb, 55);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Technology', 26, 'ねじ切りダイスは、めねじのねじ切りに用いる工具である。', 'Bàn ren là dụng cụ dùng để cắt ren trong.', NULL, '×', 'Bàn ren (ダイス) dùng để tạo ren ngoài (おねじ). Dụng cụ thông dụng tạo ren trong (めねじ) là tarô (タップ). Phát biểu sai do đổi ren ngoài thành ren trong. Ghi nhớ cặp ダイス → おねじ và タップ → めねじ.', '[{"term": "ねじ切り", "reading": "ねじきり", "meaning": "cắt ren"}, {"term": "ダイス", "reading": "ダイス", "meaning": "bàn ren"}, {"term": "めねじ", "reading": "めねじ", "meaning": "ren trong"}, {"term": "おねじ", "reading": "おねじ", "meaning": "ren ngoài"}]'::jsonb, 56);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Technology', 27, 'バイトの刃部の逃げ面が工作物と摩擦して生じる摩耗をフランク摩耗という。', 'Dạng mòn do mặt sau của phần lưỡi dao tiện ma sát với phôi được gọi là mòn mặt sau (flank wear).', NULL, '○', '逃げ面 là mặt sau của dao, nằm sát bề mặt phôi đã gia công. Khi mặt này cọ với phôi, hình thành フランク摩耗. Phân biệt với クレータ摩耗 là hõm mòn trên mặt trước do tiếp xúc với phoi. Vị trí mặt dao và đối tượng tiếp xúc là hai dấu hiệu để phân loại.', '[{"term": "逃げ面", "reading": "にげめん", "meaning": "mặt sau của dao"}, {"term": "摩擦", "reading": "まさつ", "meaning": "ma sát"}, {"term": "フランク摩耗", "reading": "フランクまもう", "meaning": "mòn mặt sau"}, {"term": "工作物", "reading": "こうさくぶつ", "meaning": "phôi, chi tiết gia công"}]'::jsonb, 57);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Technology', 28, '旋盤の切削速度は、次の式で表される。  
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Technology', 29, '旋盤の外径加工において、主軸の回転速度が一定のとき、工作物の直径が大きくなるほど切削速度は遅くなる。', 'Trong tiện đường kính ngoài, khi tốc độ quay trục chính không đổi, đường kính phôi càng lớn thì tốc độ cắt càng chậm.', NULL, '×', 'Theo V = πDN/1000, khi N không đổi thì V tỷ lệ thuận với D. Đường kính càng lớn, tốc độ cắt càng lớn, trái với phát biểu. Ví dụ cùng 600 vòng/phút, D = 100 mm cho tốc độ cắt gấp đôi D = 50 mm. Đừng nhầm tốc độ quay của trục với tốc độ dài trên chu vi phôi.', '[{"term": "外径加工", "reading": "がいけいかこう", "meaning": "gia công đường kính ngoài"}, {"term": "回転速度", "reading": "かいてんそくど", "meaning": "tốc độ quay"}, {"term": "一定", "reading": "いってい", "meaning": "không đổi"}, {"term": "遅くなる", "reading": "おそくなる", "meaning": "trở nên chậm hơn"}]'::jsonb, 59);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, answer_label, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', 'Technology', 30, '日本産業規格(JIS)によれば、工作機械関係では、普通は回転速度を毎分当たりの回転数(min⁻¹)で表す。', 'Theo JIS, trong lĩnh vực máy công cụ, tốc độ quay thường được biểu diễn bằng số vòng quay mỗi phút (min⁻¹).', NULL, '○', 'min⁻¹ nghĩa là trên mỗi phút; trong ngữ cảnh quay của máy công cụ, nó biểu thị số vòng/phút. Vì thế N = 600 min⁻¹ được hiểu là 600 vòng mỗi phút. Phân biệt với m/min, là đơn vị tốc độ cắt theo chiều dài. Số mũ −1 chỉ nghịch đảo đơn vị phút, không phải số vòng quay âm.', '[{"term": "毎分当たり", "reading": "まいふんあたり", "meaning": "trên mỗi phút"}, {"term": "回転数", "reading": "かいてんすう", "meaning": "số vòng quay"}, {"term": "工作機械関係", "reading": "こうさくきかいかんけい", "meaning": "lĩnh vực máy công cụ"}, {"term": "表す", "reading": "あらわす", "meaning": "biểu diễn"}, {"term": "～とは、～をいう。", "reading": "～とは、～をいう。", "meaning": "“X là / được gọi là Y.” Xác định đúng đối tượng định nghĩa, nhất là tên dụng cụ hoặc dạng mòn."}, {"term": "一般に、～。", "reading": "いっぱんに、～。", "meaning": "“Nhìn chung, …” Đánh giá đặc tính thông thường; không lấy trường hợp đặc biệt để thay quy tắc của đề."}, {"term": "～によれば、～。", "reading": "～によれば、～。", "meaning": "“Theo …” Kiểm tra định nghĩa, ký hiệu hoặc yêu cầu của quy định được nêu."}, {"term": "～よりも～のほうが～。", "reading": "～よりも～のほうが～。", "meaning": "“So với A, B … hơn.” Xác định thứ tự A/B và đặc tính so sánh: bôi trơn, làm mát, độ cứng."}, {"term": "～に比べて～。", "reading": "～にくらべて～。", "meaning": "“So với …” Xác định chiều tăng hoặc giảm trước khi chọn đúng/sai."}, {"term": "～の場合／～とき、～。", "reading": "～のばあい／～とき、～。", "meaning": "“Trong trường hợp / khi …” Không bỏ điều kiện: cùng số cực, cùng độ trượt, thay đá mài."}, {"term": "～が同じ場合／同一の～において", "reading": "～がおなじばあい／どういつの～において", "meaning": "“Khi … giống nhau / trong cùng …” Giữ các điều kiện này cố định khi so sánh."}, {"term": "～が一定のとき", "reading": "～がいっていのとき", "meaning": "“Khi … không đổi.” Trong V = πDN/1000, nếu N không đổi thì V tăng theo D."}, {"term": "～ほど、～。", "reading": "～ほど、～。", "meaning": "“Càng … càng …” Kiểm tra quan hệ tăng/giảm; lưu ý câu có thể khẳng định quá mức."}, {"term": "次の式で表される。", "reading": "つぎのしきであらわされる。", "meaning": "“Được biểu diễn bằng công thức sau.” Kiểm tra tử/mẫu, đơn vị và hệ số đổi đơn vị."}, {"term": "ただし、～とする。", "reading": "ただし、～とする。", "meaning": "“Trong đó / với quy ước …” Đọc đầy đủ định nghĩa biến và điều kiện áp dụng."}, {"term": "～の一つとして、～がある。", "reading": "～のひとつとして、～がある。", "meaning": "“Một trong các … là …” Chỉ cần ví dụ được nêu thuộc nhóm đó, không cần là lựa chọn duy nhất."}, {"term": "～以上／～以下", "reading": "～いじょう／～いか", "meaning": "“Từ … trở lên / không quá …” Bao gồm giá trị bằng ngưỡng."}, {"term": "～しなければならない。", "reading": "～しなければならない。", "meaning": "“Phải …” Với câu an toàn, đọc đúng hành động bắt buộc và thời điểm thực hiện."}, {"term": "下図の～は～である。", "reading": "かずの～は～である。", "meaning": "“X trong hình dưới là Y.” Đối chiếu trực tiếp hình, nhãn và vị trí lưỡi cắt; không bỏ hình."}, {"term": "～を表す。", "reading": "～をあらわす。", "meaning": "“Biểu thị …” Kiểm tra đúng đại lượng: mz là đường kính vòng chia, không phải đường kính ngoài."}, {"term": "前もって～／徐々に～", "reading": "まえもって～／じょじょに～", "meaning": "“Trước đó / từ từ.” Giữ đúng trình tự thao tác: có lỗ trước khi doa; tăng tải dần trong thử kéo."}, {"term": "～を取り去ると、元の形に戻る。", "reading": "～をとりさると、もとのかたちにもどる。", "meaning": "“Khi bỏ …, trở lại hình dạng cũ.” Nhận biết đàn hồi và điều kiện tải nằm trong giới hạn."}]'::jsonb, 60);
